#!/usr/bin/env bash
#
# Generate every language's SDK from api/openapi.yaml.
#
# One script rather than a step per language, because the point is that they are
# generated together from one document: a language left out of a regeneration is
# a language that silently describes an API that no longer exists.
#
# Go is generated by a different tool deliberately. oapi-codegen is the better
# generator for Go — it emits idiomatic types and an idiomatic client, where
# openapi-generator's Go output is generic — and it is already wired through
# `go:generate` next to the code it produces. Everything else uses
# openapi-generator, pinned by version, so the output is the same on every
# machine.
#
# Usage:
#   hack/generate-sdks.sh            # every language
#   hack/generate-sdks.sh python     # just one, for iterating
set -euo pipefail

REPO_ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
SPEC="$REPO_ROOT/api/openapi.yaml"
GENERATORS="$REPO_ROOT/api/generators"

# Pinned, not "latest": the generated code is committed, so a moving version
# would show up as a large diff nobody asked for and nobody can review. Bumping
# this is a deliberate act with its own commit.
OPENAPI_GENERATOR_VERSION="7.17.0"

# The generator is a Java program. Downloaded rather than vendored — it is 30MB,
# and a jar in the tree is a jar nobody updates.
CACHE="$REPO_ROOT/.cache"
JAR="$CACHE/openapi-generator-cli-${OPENAPI_GENERATOR_VERSION}.jar"
JAR_URL="https://repo1.maven.org/maven2/org/openapitools/openapi-generator-cli/${OPENAPI_GENERATOR_VERSION}/openapi-generator-cli-${OPENAPI_GENERATOR_VERSION}.jar"

log()  { printf '\033[1;34m[sdk]\033[0m %s\n' "$*"; }
die()  { printf '\033[1;31m[sdk]\033[0m %s\n' "$*" >&2; exit 1; }

[ -f "$SPEC" ] || die "no spec at $SPEC"

# ── Go ──────────────────────────────────────────────────────────────────────

generate_go() {
  log "go     (oapi-codegen, from sdk/go)"
  ( cd "$REPO_ROOT" && go generate ./sdk/go )
}

# ── the languages openapi-generator covers ──────────────────────────────────

ensure_jar() {
  [ -f "$JAR" ] && return
  command -v java >/dev/null 2>&1 || die "java is required to run openapi-generator; install a JRE (or a JDK to also compile the Java SDK)"
  command -v curl >/dev/null 2>&1 || die "curl is required to fetch the generator"
  mkdir -p "$CACHE"
  log "downloading openapi-generator $OPENAPI_GENERATOR_VERSION"
  curl -fsSL --retry 3 -o "$JAR.tmp" "$JAR_URL" || die "could not download the generator from $JAR_URL"
  mv "$JAR.tmp" "$JAR"
}

# generate runs the generator for one language.
#
# Output goes straight into sdk/<lang>, and openapi-generator overwrites the
# files it produces while leaving everything else alone — which is what lets the
# hand-written parts of a language directory survive a regeneration.
#
# The ignore file is the exception. openapi-generator reads
# `.openapi-generator-ignore` from *inside* the output directory, before it
# writes anything, so it cannot live there: the first thing anyone does when the
# output looks wrong is delete the directory, and that would take the ignore
# file with it and quietly regenerate all the noise it was suppressing. It is
# kept beside the generator config instead and copied in for the run.
generate_lang() {
  local lang="$1"
  local config="$GENERATORS/$lang.yaml"
  [ -f "$config" ] || die "no generator config at $config"

  local out="$REPO_ROOT/sdk/$lang"
  local ignore="$GENERATORS/$lang.openapi-generator-ignore"
  mkdir -p "$out"
  if [ -f "$ignore" ]; then
    cp "$ignore" "$out/.openapi-generator-ignore"
  fi

  log "$(printf '%-6s' "$lang") (openapi-generator $OPENAPI_GENERATOR_VERSION)"
  java -jar "$JAR" generate \
    -i "$SPEC" \
    -c "$config" \
    -o "$out" \
    --global-property apiDocs=false,modelDocs=false,apiTests=false,modelTests=false \
    >/dev/null
}

# ── run ─────────────────────────────────────────────────────────────────────

want="${1:-}"

if [ -z "$want" ] || [ "$want" = "go" ]; then
  # oapi-codegen is a Go program and is the only generator that needs nothing
  # else, so it runs first: a machine without a JRE still produces the Go SDK
  # and is then told what is missing, rather than the run dying before it has
  # done anything. A missing JRE is a real situation — this repository's own
  # development machine is one — while the other three languages are covered by
  # the workflow, which installs a JDK.
  generate_go
fi

languages=(python typescript java)
if [ -n "$want" ] && [ "$want" != "go" ]; then
  languages=("$want")
fi

if [ "${#languages[@]}" -gt 0 ]; then
  # Run rather than `command -v`: on macOS /usr/bin/java is a stub that exists
  # and only fails when something actually executes it, so a presence check
  # passes on a machine with no runtime. The message that follows is the JVM's —
  # "Unable to locate a Java Runtime" — which is why this is here, saying which
  # languages were skipped and what would generate them.
  #
  # Checked before the download path too, so a cached jar does not skip it.
  java -version >/dev/null 2>&1 || die "a Java runtime is required to generate the Python, TypeScript and Java SDKs; install a JRE (or a JDK to also compile the Java SDK). The Go SDK is generated already."
  ensure_jar
  for lang in "${languages[@]}"; do
    generate_lang "$lang"
  done
fi

log "done"
